async def execute(minion, state, pillar=""):
    """Apply Salt state."""
    api = env['saltstack.ai.config']
    kwargs = {}
    if pillar:
        import json
        kwargs["pillar"] = json.loads(pillar)
    return api.salt_call("local", minion, "state.apply", state, **kwargs)

async def execute(minion, filter=""):
    """List processes."""
    api = env['saltstack.ai.config']
    if filter:
        cmd = f"ps aux | grep -v grep | grep {filter} || echo 'No matching processes'"
    else:
        cmd = "ps aux --sort=-%mem | head -20"
    return api.salt_call("local", minion, "cmd.run", cmd)

async def execute(host):
    """Fetch Zabbix host info."""
    api = env['saltstack.ai.config']
    result = api.call("host.get", {
        "output": "extend",
        "filter": {"host": [host]},
        "selectInterfaces": "extend",
        "selectItems": "extend",
    })
    return str(result)

async def execute(host="", recent="true", limit=50):
    """Fetch Zabbix problems."""
    api = env['saltstack.ai.config']
    params = {
        "output": "extend",
        "recent": recent == "true",
        "sortfield": ["eventid"],
        "sortorder": "DESC",
        "limit": limit,
    }
    if host:
        params["hostids"] = host
    return api.zabbix_call("problem.get", params)

async def execute(event_id, message="Acknowledged by Infrastructure Operator"):
    """Acknowledge Zabbix alert."""
    api = env['saltstack.ai.config']
    result = api.call("event.acknowledge", {
        "eventids": [event_id],
        "action": 1,
        "message": message,
    })
    return str(result)

async def execute(host, key_pattern=""):
    """Fetch Zabbix item."""
    api = env['saltstack.ai.config']
    params = {"output": "extend", "host": host}
    if key_pattern:
        params["search"] = {"key_": key_pattern}
    result = api.call("item.get", params)
    return str(result)

async def execute(host="", only_problem="true"):
    """Fetch Zabbix triggers."""
    api = env['saltstack.ai.config']
    params = {
        "output": "extend",
        "selectHosts": ["hostid", "host"],
        "sortfield": "priority",
        "sortorder": "DESC",
    }
    if only_problem == "true":
        params["filter"] = {"value": 1}
    if host:
        params["hostids"] = [host]
    return api.zabbix_call("trigger.get", params)
